const instType = n => /^(NIT |MNIT|MANIT|MNNIT|SVNIT|VNIT)/.test(n)?'NIT':(/^IIIT/.test(n)?'IIIT':(/^SPA/.test(n)?'SPA':'Univ./Other'));
let mMetric='programs', mQ='A', mState=null, mFocus=null;
const NODATA='#EFE8D6', RAMP=['#E8DFC8','#B7C2DC','#7B91C2','#3D5DA3','#0E3A8A'];
function divColor(v){ const t=Math.max(-0.3,Math.min(0.3,v))/0.3; const mix=(a,b,k)=>a.map((x,i)=>Math.round(x+(b[i]-x)*k)); const base=[236,239,247],nv=[14,58,138],og=[255,107,10]; return `rgb(${t>=0?mix(base,nv,t):mix(base,og,-t)})`; }
function aggPrograms(list, qf){
  const all=list.filter(d=>d.f26!=null&&(qf==='A'||d.q===qf));
  const m=list.filter(d=>d.s==='B'&&d.t==='E'&&(qf==='A'||d.q===qf));
  return {n:all.length, m:m.length, e:cnt(m,'E'), s:cnt(m,'S'), t:cnt(m,'T'), mp:m.length>=3?med(m.map(d=>d.pct)):null, mpAny:med(m.map(d=>d.pct)), m25:med(m.map(d=>d.f25)), m26:med(m.map(d=>d.f26)), r1:med(m.map(d=>d.r1pct))};
}
const instNames=Object.keys(INST_GEO);
const byInst={}; D.forEach(d=>(byInst[d.n]=byInst[d.n]||[]).push(d));
const stateInsts={}; instNames.forEach(n=>{(stateInsts[INST_GEO[n].s]=stateInsts[INST_GEO[n].s]||[]).push(n);});
const stateList = st => (stateInsts[st]||[]).flatMap(n=>byInst[n]||[]);
function mixBar(a,cls=''){ const n=a.m||1; return `<div class="tmix ${cls}"><i class="tm-e" style="width:${a.e/n*100}%"></i><i class="tm-s" style="width:${a.s/n*100}%"></i><i class="tm-t" style="width:${a.t/n*100}%"></i></div>`; }
function quotaMixHTML(list){
  return ['C','N'].map(q=>{ const a=aggPrograms(list,q);
    if(!a.m) return `<div class="qmix"><div class="top"><span class="qn">${q==='C'?'DASA-CIWG':'DASA Non-CIWG'}</span><span class="qs">no matched programs</span></div></div>`;
    const col=a.mpAny<-0.05?'#B24300':(a.mpAny>0.05?NAVY:MUTED);
    return `<div class="qmix"><div class="top"><span class="qn">${q==='C'?'DASA-CIWG':'DASA Non-CIWG'}</span><span class="qv" style="color:${col}">${pc(a.mpAny)}</span></div>${mixBar(a)}
    <div class="qs">${a.t} tougher · ${a.s} stable · ${a.e} easier &nbsp;|&nbsp; median close ${fmt(Math.round(a.m25))} → ${fmt(Math.round(a.m26))}${a.m<5?' &nbsp;*few programs':''}</div></div>`; }).join('');
}
function stateAgg(st){ return aggPrograms(stateList(st), mQ); }
function stateValue(st){ const a=stateAgg(st); return mMetric==='programs'?a.n:a.mp; }

let mapProj, mapPath;
function drawMap(){
  const svg=d3.select('#india-map'); svg.selectAll('*').remove();
  mapProj=d3.geoMercator().fitSize([MAP_W,MAP_H],GEO); mapPath=d3.geoPath().projection(mapProj);
  svg.append('g').attr('class','states-layer'); svg.append('g').attr('class','pins-layer');
  svg.select('.states-layer').selectAll('path.state').data(GEO.features).enter().append('path')
    .attr('class',d=>'state'+(stateInsts[d.properties.st_nm]?' has':'')).attr('d',mapPath)
    .on('click',(e,d)=>{const st=d.properties.st_nm; if(stateInsts[st]) selectState(st,null);})
    .on('mousemove',(e,d)=>{const st=d.properties.st_nm; if(!stateInsts[st]) return; const a=stateAgg(st); showTip(e,`<b>${st}</b><br>${a.n} programs · ${stateInsts[st].length} institutes<br>Median change ${a.mp==null?'n/a':pc(a.mp)}`);})
    .on('mouseleave',hideTip);
  svg.select('.pins-layer').selectAll('circle.pin').data(instNames.map(n=>({n,...INST_GEO[n]}))).enter().append('circle').attr('class','pin')
    .attr('cx',d=>mapProj([d.lng,d.lat])[0]).attr('cy',d=>mapProj([d.lng,d.lat])[1]).attr('r',0)
    .on('mousemove',(e,d)=>{const a=aggPrograms(byInst[d.n],mQ); showTip(e,`<b>${d.n}</b> · ${d.c}<br>${a.n} programs in 2026<br>Median change ${a.mp==null?'n/a':pc(a.mp)}`);})
    .on('mouseleave',hideTip)
    .on('click',(e,d)=>selectState(d.s,d.n))
    .transition().duration(450).delay((d,i)=>i*10).attr('r',d=>pinR(d));
  paintMap();
}
const pinR = d => { const a=aggPrograms(byInst[d.n],mQ); return 5+Math.min(8,Math.sqrt(a.n)*1.15); };
function paintMap(){
  const svg=d3.select('#india-map');
  const vals=Object.keys(stateInsts).map(stateValue).filter(v=>v!=null);
  const max=Math.max(...Object.keys(stateInsts).map(st=>stateAgg(st).n),1);
  svg.selectAll('path.state').attr('fill',d=>{const st=d.properties.st_nm; if(!stateInsts[st]) return NODATA;
    if(mMetric==='programs'){const v=stateAgg(st).n; if(!v) return NODATA; const r=v/max; return r<.06?RAMP[0]:r<.14?RAMP[1]:r<.3?RAMP[2]:r<.6?RAMP[3]:RAMP[4];}
    const v=stateAgg(st).mp; return v==null?'#E3DCC8':divColor(v);})
    .classed('selected',d=>d.properties.st_nm===mState);
  svg.selectAll('circle.pin').attr('fill',d=>{const a=aggPrograms(byInst[d.n],mQ); return a.mp==null?'#9AA2B5':(a.mp<-0.05?ORANGE:(a.mp>0.05?NAVY:'#E89A1C'));})
    .attr('r',d=>pinR(d)).classed('sel',d=>d.n===mFocus);
  document.getElementById('map-legend').innerHTML = (mMetric==='programs'
    ? `<span>Fewer programs</span><div class="ramp">${RAMP.map(c=>`<i style="background:${c}"></i>`).join('')}</div><span>More</span>`
    : `<span>Tougher</span><div class="ramp">${[-.3,-.15,0,.15,.3].map(v=>`<i style="background:${divColor(v)}"></i>`).join('')}</div><span>Easier</span>`)
    + `<span class="dot" style="--c:${ORANGE}">Tougher</span><span class="dot" style="--c:#E89A1C">Stable</span><span class="dot" style="--c:${NAVY}">Easier</span><span class="dot" style="--c:#9AA2B5">Few / no data</span>`;
}
function showTip(e,html){const t=document.getElementById('tip'); t.innerHTML=html; t.style.left=(e.clientX+14)+'px'; t.style.top=(e.clientY+14)+'px'; t.style.opacity=1;}
function hideTip(){document.getElementById('tip').style.opacity=0;}

function renderPanel(){
  const p=document.getElementById('rightPanel');
  if(!mState){
    const all=instNames.flatMap(n=>byInst[n]); const a=aggPrograms(all,mQ);
    const sts=Object.keys(stateInsts).map(st=>({st,a:stateAgg(st),ni:stateInsts[st].length}));
    const key=mMetric==='programs'?(x=>x.a.n):(x=>x.a.mp==null?-9:-x.a.mp);
    sts.sort((x,y)=>key(y)-key(x)||x.st.localeCompare(y.st));
    const top=sts.filter(x=>mMetric==='programs'?x.a.n>0:x.a.mp!=null).slice(0,10);
    const mxv=Math.max(...top.map(x=>mMetric==='programs'?x.a.n:Math.abs(x.a.mp)),0.01);
    p.innerHTML=`<div class="drill-header"><div class="drill-title"><small>India overview</small>All states</div></div>
      <div class="dstats"><div><b>${instNames.length}</b><span>Institutes</span></div><div><b>${a.n}</b><span>Programs 2026</span></div><div><b>${a.m}</b><span>Matched</span></div><div><b>${pc(a.mpAny)}</b><span>Median change</span></div></div>
      <div class="drill-section-title">Median trend mix by quota</div>${quotaMixHTML(all)}
      <div class="drill-section-title">${mMetric==='programs'?'States by programs offered':'States where cut-offs tightened most'}</div>
      <ol class="ranked">${top.map((x,i)=>{const v=mMetric==='programs'?x.a.n:x.a.mp; const w=Math.abs(v)/mxv*100; return `<li data-st="${x.st}" tabindex="0"><span class="rk">${String(i+1).padStart(2,'0')}</span><div><div class="nm">${x.st} <span style="font-weight:400;color:var(--muted);font-size:12px">· ${x.ni} inst.</span></div><div class="bar"><i style="width:${w}%;background:${mMetric==='programs'?NAVY:(v<0?ORANGE:NAVY)}"></i></div></div><span class="vl" style="color:${mMetric==='programs'?NAVY:(v<0?'#B24300':NAVY)}">${mMetric==='programs'?v:pc(v)}</span></li>`;}).join('')}</ol>
      <div class="note-sm">Click a state on the map, or a row above, for college details. Median change uses matched engineering programs only; states with fewer than 3 are left out of the ranking.</div>`;
    p.querySelectorAll('.ranked li').forEach(li=>{const go=()=>selectState(li.dataset.st,null); li.addEventListener('click',go); li.addEventListener('keydown',e=>{if(e.key==='Enter')go();});});
    return;
  }
  const list=stateList(mState), a=aggPrograms(list,mQ), insts=stateInsts[mState].slice();
  const ia=n=>aggPrograms(byInst[n],mQ);
  insts.sort((x,y)=>ia(y).n-ia(x).n||x.localeCompare(y));
  p.innerHTML=`<div class="drill-header"><div class="drill-title"><small>State drill-down</small>${mState}</div><button class="drill-back" id="back">India view</button></div>
    <div class="dstats"><div><b>${insts.length}</b><span>Institutes</span></div><div><b>${a.n}</b><span>Programs 2026</span></div><div><b>${a.m}</b><span>Matched</span></div><div><b>${pc(a.mpAny)}</b><span>Median change</span></div></div>
    <div class="drill-section-title">Median trend mix by quota</div>${quotaMixHTML(list)}
    <div class="drill-section-title">Colleges · ${insts.length}</div>
    ${insts.map(n=>{const x=ia(n), g=INST_GEO[n], progs=byInst[n].filter(d=>d.f26!=null&&(mQ==='A'||d.q===mQ)).sort((u,v)=>(u.t==='A')-(v.t==='A')||u.f26-v.f26);
      const col=x.mpAny==null?MUTED:(x.mpAny<-0.05?'#B24300':(x.mpAny>0.05?NAVY:MUTED));
      return `<details class="inst${n===mFocus?' focus':''}" data-n="${n}" ${n===mFocus?'open':''}><summary><span class="in">${n}<small>${instType(n)}</small></span><span class="pill ${x.mpAny<0?'neg':'pos'}" style="${x.mpAny==null?'background:var(--cream-2);color:var(--muted)':''}">${x.mpAny==null?'no trend':pc(x.mpAny,0)}</span>
        <span class="is">${g.c} · ${x.n} programs${x.m?` · median close ${fmt(Math.round(x.m26))}`:''}</span>${x.m?mixBar(x):'<span></span>'}</summary>
        <div class="pscroll"><table class="ptab"><thead><tr><th>Program</th><th>Quota</th><th class="r">2025</th><th class="r">2026</th><th class="r">Δ</th></tr></thead><tbody>
        ${progs.map(d=>`<tr><td>${d.p}${d.s==='N'?'<span class="badge2 badge-new">new</span>':''}</td><td class="mn">${QN[d.q]}</td><td class="r mn">${fmt(d.f25)}</td><td class="r mn">${fmt(d.f26)}</td><td class="r">${d.pct==null?'<span class="mn" style="color:var(--muted)">—</span>':`<span class="pill ${d.pct<0?'neg':'pos'}">${pc(d.pct,0)}</span>`}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No programs under this quota.</td></tr>'}
        </tbody></table></div></details>`;}).join('')}
    <div class="note-sm">Closing ranks are final-round (2025 R3, 2026 R2), open seats. Δ = 2026 vs 2025; negative means tougher. Architecture programs use a separate rank list.</div>`;
  document.getElementById('back').addEventListener('click',()=>selectState(null,null));
  if(mFocus){const el=p.querySelector('details.inst.focus'); if(el&&window.innerWidth<=920) setTimeout(()=>el.scrollIntoView({block:'center',behavior:'smooth'}),60);}
}
function selectState(st,inst){ mState=st; mFocus=inst; paintMap(); renderPanel(); }
function refreshMap(){ paintMap(); renderPanel(); }
document.querySelectorAll('.filter-pill[data-metric]').forEach(b=>b.addEventListener('click',()=>{
  document.querySelectorAll('.filter-pill[data-metric]').forEach(x=>x.setAttribute('aria-pressed',x===b)); mMetric=b.dataset.metric; refreshMap(); }));
bindSeg('seg-map',v=>{mQ=v; refreshMap();});
(()=>{ const a=aggPrograms(instNames.flatMap(n=>byInst[n]),'A'); document.getElementById('b-prog').textContent=a.n; document.getElementById('b-chg').textContent=pc(a.mpAny);
  if(typeof d3==='undefined'){document.getElementById('india-map').outerHTML='<div class="empty">The map library could not load. College details are still available in the panel.</div>';}
  else drawMap();
  renderPanel(); })();

/* ---------- UI ---------- */
document.querySelectorAll('.fq button').forEach(b=>b.addEventListener('click',()=>{const f=b.parentElement, o=f.classList.toggle('open'); b.setAttribute('aria-expanded',o);}));
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target);}}),{threshold:.08});
document.querySelectorAll('.reveal').forEach(el=>io.observe(el));
